import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <int TPB>
__global__ void group_norm_forward_kernel(
    const __half* __restrict__ input,
    __half* __restrict__ output,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    int N, int C, int H, int W,
    int G, float eps)
{
    // one block per (batch, group)
    const int ng = blockIdx.x;                // 0 .. N*G-1
    const int batch = ng / G;
    const int g = ng % G;

    const int channels_per_group = C / G;
    const int spatial = H * W;
    const int elems_per_group = channels_per_group * spatial;

    const int c_start = g * channels_per_group;

    // shared memory for reduction
    __shared__ float s_sum[TPB];
    __shared__ float s_sumsq[TPB];

    float sum = 0.0f;
    float sumsq = 0.0f;

    // first pass: compute sum and sum of squares
    for (int idx = threadIdx.x; idx < elems_per_group; idx += TPB) {
        int ch_offset = idx / spatial;          // 0 .. channels_per_group-1
        int sp_offset = idx % spatial;
        int h = sp_offset / W;
        int w = sp_offset % W;

        int c = c_start + ch_offset;
        int linear_idx = ((batch * C + c) * H + h) * W + w;

        __half val_h = input[linear_idx];
        float val = __half2float(val_h);
        sum   += val;
        sumsq += val * val;
    }

    s_sum[threadIdx.x]   = sum;
    s_sumsq[threadIdx.x] = sumsq;
    __syncthreads();

    // reduction in shared memory
    #pragma unroll
    for (int stride = TPB / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            s_sum[threadIdx.x]   += s_sum[threadIdx.x + stride];
            s_sumsq[threadIdx.x] += s_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float mean = s_sum[0] / static_cast<float>(elems_per_group);
    float var  = s_sumsq[0] / static_cast<float>(elems_per_group) - mean * mean;
    float inv_std = rsqrtf(var + eps);

    // second pass: normalize and apply affine
    for (int idx = threadIdx.x; idx < elems_per_group; idx += TPB) {
        int ch_offset = idx / spatial;
        int sp_offset = idx % spatial;
        int h = sp_offset / W;
        int w = sp_offset % W;

        int c = c_start + ch_offset;
        int linear_idx = ((batch * C + c) * H + h) * W + w;

        float x = __half2float(input[linear_idx]);
        float norm = (x - mean) * inv_std;

        float wgt = __half2float(weight[c]);
        float b   = __half2float(bias[c]);

        float y = norm * wgt + b;
        output[linear_idx] = __float2half(y);
    }
}

// C++ interface
at::Tensor group_norm_forward(
    at::Tensor input,
    at::Tensor weight,
    at::Tensor bias,
    int64_t num_groups,
    double eps)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda() && bias.is_cuda(), "weight/bias must be CUDA");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(weight.dtype() == torch::kHalf && bias.dtype() == torch::kHalf,
                "weight/bias must be fp16");

    const auto N = input.size(0);
    const auto C = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);
    const int G = static_cast<int>(num_groups);
    const float eps_f = static_cast<float>(eps);

    auto output = at::empty_like(input);

    const int blocks = N * G;
    const int threads = 256;   // TPB

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "group_norm_forward_kernel", ([&] {
        group_norm_forward_kernel<threads><<<blocks, threads>>>(
            reinterpret_cast<const __half*>(input.data_ptr<at::Half>()),
            reinterpret_cast<__half*>(output.data_ptr<at::Half>()),
            reinterpret_cast<const __half*>(weight.data_ptr<at::Half>()),
            reinterpret_cast<const __half*>(bias.data_ptr<at::Half>()),
            N, C, H, W,
            G, eps_f);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(std::string("CUDA kernel error: ") + cudaGetErrorString(err));
    }

    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("group_norm_forward", &group_norm_forward, "GroupNorm forward (fp16)");
}
'''

ext = load_inline(name='gn_ext',
                  cpp_sources='',
                  cuda_sources=src,
                  functions=['group_norm_forward'],
                  verbose=False)

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    """
    def __init__(self, num_features: int, num_groups: int, eps: float = 1e-5):
        super().__init__()
        self.num_groups = num_groups
        self.eps = eps
        # affine parameters (fp16)
        self.weight = nn.Parameter(torch.randn(num_features, dtype=torch.float16))
        self.bias   = nn.Parameter(torch.randn(num_features, dtype=torch.float16))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # ensure fp16 and contiguous
        x = x.to(torch.float16).contiguous()
        w = self.weight.contiguous()
        b = self.bias.contiguous()
        out = ext.group_norm_forward(x, w, b, self.num_groups, self.eps)
        return out
